/* anime_eva_25_end — episodes 25-26 + End of Evangelion, 06:32-06:47. The dawn of one day, the marathon's end: Ren talks to the screen through the abstract finale and the movie, then faces the final choice — sleep with Evangelion in his head, or stay in mecha-art instead of the real mecha. Both endings: the catastrophes happen anyway. Nausicaa and the rest are a separate browse path, not a sequel to Eva. */
(function (root) {
    'use strict';
    var registry = root.SeirinStory = root.SeirinStory || { arcs: {}, register: function (name, factory) { this.arcs[name] = factory; } };
    registry.register('anime_eva_25_end', function (api) {
        var vn = api.vn;
        var engine = api.engine;
        var routeChoice = api.routeChoice;
        var effectChoice = api.effectChoice;
        return {
            AnimeEva_Ep25_26: [
                vn.goTo('Квартира: Ева 25-26 — внутренний мир'),
                'show scene workshop with fadeIn duration 1s',
                'p Двадцать пятая серия. Театр со стульями. Пустота, стулья, и все говорят с Синдзи. Без Евы, без ангелов, без мира. Просто люди и слова. И я думаю: вот оно. Куда меня всю ночь вело. Не в бой. Сюда. В театр.',
                'p Почему театр? Потому что театр — это место, где люди говорят правду, притворяясь. Или притворяются, говоря правду. Я не знаю. Но я сижу в этом театре вместе с ними. На стуле. В пустоте. Только у меня нет декораций. У меня квартира.',
                'p Аска говорит: «Я ненавижу всех. Но хочу, чтобы меня любили». И я сижу и понимаю, что это самое честное признание за весь сериал. Противоречие, которое объясняет её лучше, чем все её крики. И я думаю: а я так умею? Сказать честно, без игры? «Я боюсь накопителя, но хочу его собрать»? Не звучит. Потому что я не боюсь его. Я боюсь, что не получится. А признавать это — отдельный навык, которым я владею мастерски.',
                'p Ненависть — это обратная сторона желания быть любимым. Она орёт «ненавижу», потому что не может сказать «любите меня». Я узнаю этот крик. Я его подавил. Теперь он выходит сериалами. И чаем в четыре утра. И вопросами, которые я задаю экрану.',
                'p Рей говорит: человек может любить себя, даже если не умеет. И у неё самой этого нет, но она формулирует. И я думаю: вот что значит понять умом, но не сердцем. Я понимаю, что надо встать и собрать контакт. Умом. А сердцем — нет. И сериал говорит, что это нормально. Что «не умею» — это не «не смогу». Наверное. Я не уверен.',
                'p Я умею себя терпеть. Это ближе к ненависти, чем к любви. И я не знаю, как из «терплю» сделать «принимаю». Может, надо просто сидеть. Как Рей. И ждать. Не знаю чего. Может, самого себя.',
                'p Мисато говорит Синдзи: ты вырос, потому что смог сказать «я ненавижу себя, но могу научиться любить». И я замираю. Потому что это ровно то, что я не могу сказать. Не потому что не хочу. Потому что не знаю, хочу ли я себя любить. И есть ли за что. И этот вопрос не закрывается. Я закрываю вкладку, но вопрос остаётся.',
                'p Альтернативный мир. Синдзи — обычный школьник, Аска — подруга детства, Рей — новенькая. И я думаю: если бы не было Евы, они были бы счастливы? Или они всё равно были бы собой, просто в других декорациях? И я думаю про себя: если бы не было накопителя, я был бы другим? Или я бы нашёл, от чего бежать?',
                'p Серия двадцать шестая. Синдзи в кресле, и все хлопают. Хлопают ему. А мне никто не хлопает. И я думаю: а я бы похлопал себе, если бы досмотрел всё это до конца? Наверное, да. Хотя бы за то, что не выключил.',
                'p Я замечаю, что в этих сериях почти нет анимации. Стоят и говорят. И это работает. Потому что иногда не нужно ничего, кроме слов. И я думаю: а я умею так? Стоять и говорить? Или я только смотрю и молчу? И кто из нас двоих — Синдзи, а кто — стул?',
                'p Синдзи говорит «я ненавижу себя». И я думаю: я тоже так говорил. Утром. В зеркало. А потом пошёл смотреть аниме. И это сработало. На время. Всё работает на время. И ничего не работает навсегда. И, наверное, это нормально.',
                'p Финал TV-версии. Хлопки. «Поздравляем». «Спасибо». Бюджет кончился, и финал — внутренний, а не внешний. И я впервые за ночь смеюсь. Не потому что смешно. Потому что это так по-человечески: не хватило денег, и ты делаешь финал из слов и хлопков. И он работает. И я думаю: а может, и мне не хватает «бюджета» на идеальные условия, и поэтому я не собираю? Или я ищу оправдание, как режиссёр искал деньги?',
                'p Послевкусие: зритель ждал внешнего разрешения, а получил внутреннее. Я понимаю это разочарование. Я тоже ждал, что Синдзи победит, мир спасётся, и всё станет понятно. А он просто говорит «спасибо». И хлопает. И я думаю: а я когда последний раз говорил «спасибо» по-настоящему, а не вежливо? Не помню. И это тоже вопрос без ответа.',
                'p «おめでとう». Поздравляю. С чем? Не сказано. С тем, что ты есть? С тем, что ты решил остаться? Я не знаю. И, кажется, не должен знать. Поздравление без причины — это, наверное, и есть любовь. Или безумие. Или одно без другого не бывает. Накопитель мигает, как будто аплодирует. Или как будто просто мигает. Я уже ничего не могу отличить.',
                { Choice: { Dialog: '',
                    EvaEnd: routeChoice('End of Evangelion', 'AnimeEva_End', { procrastination: 2, philosophical_depth: 3 })
                } }
            ],

            AnimeEva_End: [
                vn.addTime(1),
                vn.goTo('Квартира: The End — 06:33, рассвет одного дня идёт'),
                'show scene workshop with fadeIn duration 1s',
                'p {{player.time_hhmm}}. Тренировка Скрэп-Титана в куполе уже идёт. Рейка в куполе, а я всё ещё в End of Evangelion. Фильм восемьдесят семь минут, смотрю без ускорения. Впервые за ночь без ускорения. Потому что это последнее. И я хочу это запомнить. Или боюсь, что не забуду.',
                'p Начало: JSSDF атакует NERV. Танки, вертолёты, кровь на лестницах. Приказ SEELE — уничтожить всех своих. И я думаю: мир не прощает тех, кто знает секрет. Я знаю свой секрет: я не собираю контакт, потому что боюсь, что не получится. И мир меня пока не атакует. Наверное, мой секрет не дорос до атаки. Или мир просто занят.',
                'p Свои против своих. Гражданская война — это когда правы все и никто. И я узнаю: я веду гражданскую войну. С собой. Уже шесть часов. И в ней тоже правы все и никто. И обе стороны — я. И обе стороны проигрывают.',
                'p Мисато тащит Синдзи к Еве-01. Целует. «Стань взрослым». И умирает. От выстрелов за дверью. Просто лежит. Без героизма, без музыки, без последних слов. И я думаю: вот так и умирают. Не красиво. А я всю ночь искал красивое. И находил. А правда — она не красивая. Она просто есть.',
                'p Поцелуй перед смертью — это когда слова уже не нужны. Или слова закончились. И я думаю: а у меня есть такие моменты? Когда слова закончились? Наверное, есть. Я их не помню. Я их заменил сериалами.',
                'p Синдзи кричит, когда она умирает. И я думаю: он впервые за сериал плачет не о себе. О ней. И я понимаю, что взросление — это когда начинаешь плакать о других. Я давно не плакал о других. Наверное, я ещё не вырос. Или вырос, но растерял это по дороге. И то и другое возможно.',
                'p Аска в озере. Ева-02 без кабеля. Серийные Евы с крыльями. И она уничтожает восемь из девяти. Пока батарея не садится. И я думаю: вот она, Аска. Лучшая. Пока не кончилась энергия. Я узнаю это: я тоже держусь, пока батарея не сядет. А потом ломаюсь и виню батарею. Хотя она просто батарея.',
                'p Восемь из девяти. А потом батарея. И я думаю: сколько я смогу? Если бы моя жизнь была боем, сколько бы я уничтожил? И что бы меня остановило? Наверное, батарея. Или страх. Одно из двух. Не знаю, какое раньше.',
                'p Серийные Евы разрывают Еву-02. Долго. С хрустом. Без музыки. И я смотрю и не отвожу взгляд, потому что это правда: мир добивает тех, кто выложился. И я думаю: а что, если я выложусь? Соберу контакт, приду в купол, а там — серийные Евы? Или я не выложусь, и тогда мне нечего бояться? И что из этого хуже, я не знаю.',
                'p Это не бой. Это казнь. И я не отвожу взгляд. Потому что отвести взгляд от казни — значит принять её. А я не принимаю. Я просто смотрю. И это тоже принятие. Я запутался. Наверное, в этом и суть: любой взгляд — это участие.',
                'p Комплементация. Все люди превращаются в LCL. Оранжевый суп. Голоса, руки тянутся, границы исчезают. И я думаю: вот оно, обещание — стать всем, не быть никем. И я понимаю, почему это так привлекательно. Потому что быть собой — больно. А быть всеми — не больно. Я бы согласился? Наверное, да. И это меня пугает больше, чем все ангелы.',
                'p А пахнет ли суп? Наверное, кровью. Как LCL Синдзи. И я думаю: все мы — суп. Просто пока в форме. И я держу форму. Пока держу. И не знаю, сколько ещё.',
                'p Внутри комплементации Синдзи выбирает вернуться. В мир, где есть боль и неопределённость. Где люди могут ранить. И я не понимаю, как он это делает. Или понимаю, но не хочу признавать: без боли нет ощущения, что ты живой. А я не чувствую себя живым уже давно. Может, поэтому мне и не страшно прокрастинировать. Я и так не живу по-настоящему. Я жду, когда начну.',
                'p Я бы выбрал суп. Наверное. Потому что в супе не надо выбирать. А потом я понимаю: я уже в супе. Я не выбирал. Я просто в нём. И сериал говорит: можно выйти. Надо только захотеть. Я не хочу. Или хочу, но не верю, что можно.',
                'p Синдзи говорит «спасибо». Миру. Людям. Себе. И я думаю: я бы хотел уметь так — говорить «спасибо» не потому что вежливо, а потому что правда. Может, этому учатся. Может, комплементация — это когда все говорят «спасибо» и не боятся. Я не боюсь. Я просто не умею. Пока. Или уже. Я не знаю.',
                'p Берег. Песок, LCL, Аска с повязкой на глазу. Синдзи рядом. Он душит её. Потом отпускает и плачет. И я думаю: он хотел проверить, что она настоящая. Что мир настоящий. Что он не один в супе. Я узнаю это желание: проверить, что рядом — настоящее. У меня никого нет рядом. Только накопитель. И он не проверяется. Он просто мигает.',
                'p Она пережила всё. И лежит. И я думаю: а что остаётся после всего? Берег. Песок. И кто-то рядом. У меня нет никого рядом. Только накопитель. И он — не Аска. Он не ответит «kimochi warui». Он вообще не отвечает. Он просто ждёт.',
                'p «Kimochi warui». Отвратительно. Аска говорит это, когда он убирает руку. И я думаю: это про прикосновение? Про возвращение в мир? Про то, что жить — отвратительно? Или про то, что жить — отвратительно, но это всё, что у нас есть? Я не знаю. И я рад, что не знаю. Потому что если бы я знал, мне было бы нечего пересматривать.',
                'p Я смотрю на Рей, которая выбирает Синдзи вместо Гэндо. И я думаю: даже она смогла выбрать. А я выбираю весь вечер — серию за серией. И мой выбор — это отсутствие выбора. Или это и есть выбор? Опять. Вопросы без ответов. Зато теперь с берегом внутри.',
                'p Фильм заканчивается. Тишина. Я сижу и не могу встать. Восемьдесят семь минут без ускорения, и теперь у меня внутри этот берег. И накопитель мигает. И я знаю, что мне надо встать. И я не встаю. И вопрос, который я задаю себе впервые вслух: я хочу вернуться в мир, где есть боль, или я хочу остаться в супе?',
                vn.addTime(14),
                'p {{player.time_hhmm}}. Рассвет за окном, и я впервые за ночь смотрю не в экран, а в окно. Ну что, мир. Я всё ещё здесь. И ты всё ещё здесь. И накопитель всё ещё здесь. Вопрос, который остался от всей ночи: кто из нас троих сдастся первым? Или мы все трое просто будем стоять и ждать?',
                'p Итого: двадцать шесть серий и фильм. Шесть часов с 00:31 до 06:47. Единственный тайтл за ночь, который я смотрел целиком, а не бегло. И я не знаю, гордиться этим или стыдиться. Наверное, и то и другое. И это, наверное, и есть честный ответ. Не один из двух, а оба сразу.',
                'p Навсикая, Key, цикады, Honkai остались в ленте нетронутыми. В эту ночь я смотрел только Еву. Всю. Вопрос: почему именно её? Может, потому что она про меня. Или потому что я про неё. Или потому что в шесть утра уже не выбираешь. Не знаю.',
                { Choice: { Dialog: '06:47. Ева кончилась. Что дальше в том же дне?',
                    EvaEndSleep: routeChoice('Идти спать с мыслями о Евангелионе', 'AnimeEva_EndSleep', { philosophical_depth: 3 }),
                    EvaEndMechaArt: routeChoice('Остаться в меха-тематике — разборы и наброски вместо отвёртки', 'AnimeEva_EndMechaArt', { procrastination: 6 })
                } }
            ],

            AnimeEva_EndSleep: [
                vn.goTo('Квартира: Сон с мыслями о Евангелионе'),
                'show scene workshop with fadeIn duration 1s',
                vn.setTime(1872),
                'p {{player.time_hhmm}}. Я закрываю ноутбук и ложусь. Синдзи остался на берегу, Аска сказала «kimochi warui», а у меня под веками — оранжевый LCL. Успеваю подумать: «завтра соберу контакт. Сегодня я хотя бы досмотрел».',
                'p Сон приходит быстро. И в нём я слышу не голоса Мисато и Каору — а сирену. Потом вторую. Потом гул, от которого вибрирует стена.',
                'p Я просыпаюсь, но не встаю. За окном — вспышки у порта. Взрывы один за другим, как барабанная дробь. Люди кричат на набережной. Дворник, который должен был мести свой метр асфальта, бежит к укрытию.',
                'p Тест Решётки 34%. Башня Акатоми гудит на пределе. В куполе должен был стоять Скрэп-Титан-04 — четырёхметровая платформа, которую я должен был собрать к 06:00. Её там нет. Вместо неё — я под одеялом, с мыслями о Еве.',
                'p Телефон мигает: Рейка, три сообщения, все без восклицательных. Последнее: «Пилот. Нас могли прикрыть». Я смотрю в потолок — тот самый, из второй серии. Потолок не отвечает.',
                'p Закрываю глаза и представляю, что я — Синдзи, и что Ева-01 сейчас поднимет меня с кровати. Она не поднимает. Она в мультике. А я в своей квартире, и город горит в том же дне, который я смотрел с 00:31 до 06:47.',
                vn.reversible({ procrastination: 3 }),
                'sys <span class="t-red">[ ФИНАЛ ПРОКРАСТИНАЦИИ · СПАТЬ С МЫСЛЯМИ О ЕВЕ · ОДИН ДЕНЬ ]</span> Катастрофы, которые он должен был предотвратить, случились. Взрывы слышал тот, кто спал. Город проиграл без боя, пока пилот смотрел мультик.',
                'end'
            ],

            AnimeEva_EndMechaArt: [
                vn.goTo('Квартира: Меха-альбом'),
                'show scene workshop with fadeIn duration 1s',
                vn.setTime(1907),
                'p {{player.time_hhmm}}. Я не ложусь. Вместо отвёртки открываю альбом и рисую: Еву-01, потом Еву-02, потом Титана — каким он должен был стать. Двенадцать набросков. Меха, которую я выбираю вместо мехи.',
                'p За окном — взрывы. Я слышу их, но не поднимаю головы. Карандаш ведёт линию брони, и это важнее того, что где-то падает настоящая броня. Так я себе говорю.',
                'p В куполе пусто. Накопитель Скрэп-Титан-04 лежит разобранным на столе, а я рисую его собранным. Разница между рисунком и реальностью — в одном обороте отвёртки. Я делаю ещё один набросок.',
                'p Рейка пишет: «Тренировка отменена. Город эвакуируют от порта». Я отвечаю стикером с Евой. Потом рисую горящий порт в стиле Евы: тени, контражур, фиолетовая дымка. Красиво. Ужасно красиво.',
                'p Люди гибнут, а я выбираю кадр для референса. Взрыв у порта пропускаю мимо ушей — как пропустил дедлайн. Меха-искусство — это тоже кабина. Только в ней не больно. Поэтому я в ней и остаюсь.',
                'p Альбом закрывается в 07:47. Двенадцать Титанов на бумаге. Ноль Титанов в куполе. Я выбирал между реальной мехой и искусством про меху — и выбрал то, что не требует затягивать болты.',
                vn.reversible({ procrastination: 6, philosophical_depth: 2 }),
                'sys <span class="t-red">[ ФИНАЛ ПРОКРАСТИНАЦИИ · ИСКУССТВО ПРО МЕХУ · ОДИН ДЕНЬ ]</span> Тот, кто вместо мехи выбрал искусство про меху, слышал взрывы, но рисовал их. Город горел, а альбом пополнялся.',
                'end'
            ]
        };
    });
}(typeof window !== 'undefined' ? window : this));
